args:
set -eu
source_file="$1"
build_dir="$2"
output_file="$3"
source_dir="$4"
case "$source_file" in
  "$source_dir"/*) ;;
  *) printf '%s\n' '这个编译任务只用于 C 目录中的 C/C++ 源文件。' >&2; exit 2 ;;
esac
case "$source_file" in
  *.c) compiler=/usr/bin/clang; standard=-std=c17 ;;
  *.cpp|*.cc|*.cxx|*.C|*.CPP|*.c++) compiler=/usr/bin/clang++; standard=-std=c++17 ;;
  *) printf '%s\n' '请先打开并保存一个 .c 或 .cpp 源文件。' >&2; exit 2 ;;
esac
mkdir -p -- "$build_dir"
exec "$compiler" "$standard" -arch arm64 -g -O0 -Wall -Wextra "$source_file" -o "$output_file"
